items=[
 dict(name='BanditRL.OnlineAdaptiveOSD.regret_bound',title='Causal adaptive OSD retains the terminal-distance residual',anchor='Theorem2.13 weighted-distance proof and the adaptive calculation preceding Eq.(4.4)',objects='For the actual causal projected trajectory with eta_t=alpha*D/sqrt(S_(t+1)) and zero-feedback skipping, the regret is bounded by (1/(2alpha)+alpha)*D*sqrt(S_T) minus the terminal squared distance times sqrt(S_T)/(2alpha D). The reusable potential theorem separately permits signed real a_t bounded above by C only at played indices, nonnegative nondecreasing weights and T>0; no terminal bound or lower bound on a_t is added.',math=r'\begin{gathered}S_t=\sum_{i<t}\|g_i\|^2,\quad \eta_t=\frac{\alpha D}{\sqrt{S_{t+1}}},\\ \sum_{t<T}(a_t-a_{t+1})w_t\le(C-a_T)w_{T-1},\\ R_T(u)\le\left(\frac1{2\alpha}+\alpha\right)D\sqrt{S_T}-\frac{\|x_T-u\|^2\sqrt{S_T}}{2\alpha D}.\end{gathered}',proof='For D>0, legal supporting planes and projection nonexpansiveness give the one-step distance and energy estimate. Summation by parts controls the distance terms with monotone weights sqrt(S_(t+1))/(2alpha D), retaining the signed terminal term. The shared adaptive-energy sum controls the feedback terms. Empty horizons vanish; D=0 forces feasible played and comparator points to coincide, so it is proved separately without dividing by D. Totalized real division makes the displayed residual zero at D=0.',delta='The signed potential lemma is an algebraic generalization of the source distance calculation; general alpha and its retained residual are a stronger support-sufficient endpoint, not a new printed theorem. Printed14 already has the factor1/2; the earlier missing-half allegation was withdrawn. '+common_delta,parents=load(RUN/'parent-direct-parent-checks-v1.json')['expected_direct_VALUE_parents'],source_id='ORABONA-V10-ADAPTIVE-POTENTIAL-PARAMETERIZED'),
 dict(name='BanditRL.OnlineAdaptiveOSD.source_eq4_4',title='The alpha-one adaptive run has the three-halves bound',anchor='Eq.(4.4), printed40/PDF52',objects='For every comparator in the feasible domain, the actual alpha=1 projected adaptive run has regret at most (3/2)*D*sqrt(S_T), including zero energy, zero diameter and the empty horizon.',math=r'\eta_t=\frac{D}{\sqrt{S_{t+1}}},\qquad R_T(u)\le\frac32D\sqrt{S_T}.',proof='Instantiate the parameterized actual-run theorem at alpha=1. The terminal residual is nonnegative before subtraction, so dropping it weakens the bound. Evaluate 1/(2alpha)+alpha=3/2. Canonical-feedback adapters separately construct legal selected supports from the shared canonical policy.',delta=common_delta,parents=['BanditRL.OnlineAdaptiveOSD.regret_bound'],source_id='ORABONA-V10-EQ4.4'),
 dict(name='BanditRL.OnlineAdaptiveBenchmark.source_theorem4_14_infimum',title='The optimized adaptive coefficient and the infimum boundary',anchor='Theorem4.14, printed40/PDF52; separately reviewed minimum/infimum repair',objects='The actual alpha=sqrt(2)/2 adaptive run satisfies R_T(u)<=D*sqrt(2*S_T). Its numerical bound equals sqrt(2) times the infimum of the fixed-energy positive-step upper-bound family. The regret inequality preserves the source regimes; the infimum display explicitly repairs unattained one-zero minima.',math=r'\begin{gathered}\eta_t=\frac{D}{\sqrt{2S_{t+1}}},\quad R_T(u)\le D\sqrt{2S_T},\\ D\sqrt{2S}=\sqrt2\inf_{\eta>0}\left(\frac{D^2}{2\eta}+\frac{\eta S}{2}\right),\\ \text{attainment}\iff(D>0\land S>0)\lor(D=0\land S=0).\end{gathered}',proof='Set alpha=sqrt(2)/2 in the general theorem and simplify its coefficient to sqrt(2), then discard the nonnegative residual. Independently reuse the shared optimal-step lower bound and positive argmin for the scalar benchmark. In each one-zero case construct arbitrarily small positive upper-bound values; the existing strict-decrease facts rule out attainment. Combine the regret inequality with this infimum identity evaluated on the energy of the actual run.',delta=common_delta+' '+repair,parents=load(RUN/'benchmark-direct-parent-checks-v1.json')['expected_direct_VALUE_parents']['source_theorem4_14_infimum'],source_id='ORABONA-V10-T4.14-INFIMUM-REPAIR')]
